                  body: 'Русскому дательному падежу («кому?») соответствует Dativ: der → dem, das → dem, die → der, во множественном числе — den, и существительное получает -n: mit den Kindern. Местоимения: mir, dir, ihm, ihr, uns, euch, ihnen / Ihnen. Dativ всегда стоит после предлогов mit, nach, aus, zu, von, bei, seit и после глаголов helfen, danken, gefallen, gehören, schmecken. Осторожно с кальками: по-русски «благодарить кого?» (винительный), а по-немецки danken + Dativ: Ich danke dir. «Мне нравится» строится так же, как в русском: Mir gefällt die Stadt.',
